      "イ": "ミトコンドリアは、内外2枚の膜に包まれ、内側の膜から内腔に向かって突出した襞状の隆起であるマトリクスを形成する、糸状又は球状の細胞小器官である。主な機能は、細胞活動のエネルギー源となるGABAを産生する。",
      "ウ": "神経細胞は、細胞体のほかに、神経情報としての興奮を伝導する樹状突起や軸索から構成される。シナプスで神経終末からアセチルコリンやドーパミン等の神経伝達物質が放出され、隣接する神経細胞の受容体に結合することで、興奮が伝達される。",
