    "difficulty": 3,
    "question": "我が国の作物生産と気象災害に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　湿害とは、農耕地の排水不良や多雨などによる土壌の過湿に起因する作物生産性の低下である。土壌間隙の空気が減少して、根の呼吸が妨げられることや病気が発生しやすくなることが原因となる。我が国では、転換畑で作られるムギやダイズなどで被害が大きく、対策が必要となる。\nB　干害とは、農地に侵入した海水などの塩分が原因で、根からの吸水が抑制されて生じる作物生産性の低下である。水不足に陥った作物は、まず成長の停止や葉の萎凋などの症状を示し、その後気孔の閉鎖や光合成速度の低下が生じる。\nC　冷害とは、主に夏季の冷温によって生じる作物生産性の低下である。イネの冷害は、穂の発育時期の冷温による花粉形成の障害などが原因となる障害型冷害と、生育期間中の冷温による生育遅延が原因となる遅延型冷害に大別される。\nD　高温害とは、作物の生育適温を上回る高温が継続した場合に発生する作物生産性の低下である。冷涼な気候を好むコムギなどの作物では高温の影響を受けやすい一方、熱帯地域を原産とするイネでは高温害が発生することは珍しく、近年においても、むしろ冷害の方が問題視されている。",
