    "question": "我が国における食料の合理的な価格の形成に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。なお、データは「令和6年度 食料・農業・農村白書（令和7年5月30日公表）」による。\n\nA　農産物の価格の動向について、令和2（2020）年の平均価格を100とした指数でみると、生鮮食品を除いた物価の上昇により農産物への需要が相対的に減退したため、令和3（2021）年1月から令和6（2024）年7月まで農産物価格指数は90を下回った。また、令和6年8月以降、米や野菜等の価格が大きく上昇したが、農業交易条件指数は令和2年の平均値である100を下回る状況が続いている。\nB　令和7（2025）年1月までの食料品の小売価格等の状況をみると、飲用牛乳では令和4（2022）年春以降の生乳の生産コスト急増に伴う乳価の引上げによる2回の価格上昇局面を除き、小売価格はほぼ横ばいになっている。また、納豆や豆腐については、製造コストが増加しているものの、小売価格の大幅な上昇はなく、おおむね横ばいの状態が続いている。\nC　合理的な費用を考慮した価格形成のためには、コストの把握・明確化やコストを考慮した取引の実施等に加え、農林漁業者との安定的な取引関係の確立、流通の合理化、環境負荷低減といった持続的な食料システムを確立することで、消費者の理解を得ながら、食料の持続的な供給を実現することが求められる。\nD　農林水産省では、令和5（2023）年度及び令和6年度において「フェアプライスプロジェクト」を実施した。このプロジェクトでは、経済的に困窮している人々にも農産物が十分に行き渡るように消費者の購買力に応じた価格を設定することや、開発途上国の生産者や労働者が適正な対価を得て、安定した生活を送れるよう配慮することなどを啓発する活動が行われている。",
