    "difficulty": 3,
    "question": "海水の性質に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　海水温を鉛直的にみると、一般に、表層では太陽熱によって温められるため高く、下層に向かうにつれて低下していく。水温の鉛直構造は、混合層、季節温度躍層、主温度躍層（永久温度躍層）、更にそれより深い層に分類される。混合層では、風や波によって生じる乱流混合の影響により、水温が鉛直方向に一定になる。\nB　深層の水温は、水圧の増加に伴う断熱圧縮によって低下する。ある水圧下にある海水を、周囲との熱交換を行わずに基準圧力まで移動させたときの水温を、ポテンシャル水温と呼ぶ。ポテンシャル水温は、水圧の増加に伴う水温変化を無視できるため、特に表層における水塊の動きを追跡するのに用いられる。\nC　外洋の表層の塩分は、赤道域や亜寒帯域では低く、亜熱帯循環系の内部では高い。このような塩分の水平分布は、海面における降水量と蒸発量の差に対応している。北太平洋の高緯度海域における塩分は、表層では低く、ある程度の深さまでは徐々に増加する。\nD　海水の密度は、主に水温、塩分、圧力によって変動し、一般に、水温が高いほど海水の密度も高くなる。また、塩分が上がるにつれて海水の密度は高くなる。海水密度の鉛直構造は、表層混合層、密度躍層、深層の3層に大別され、密度躍層より深くなると密度が急激に低下する。",
