    "difficulty": 3,
    "question": "次は、真骨魚類の浸透圧調節に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n一般に、真骨魚類では、鰓、腎臓及び腸が浸透圧調節で重要な役割を果たしている。［A］は淡水適応ホルモンであり、浸透圧調節器官の上皮の透過性を低下させ、イオンの体外への流出を防ぐ。［A］は腎臓にも作用し、糸球体濾過量を［B］させる。そして、膀胱でナトリウムイオンの再吸収を増加させ、水の再吸収を低下させる。\nコルチゾルは海水適応ホルモンであり、［C］で産生される。コルチゾルは鰓に作用し、海水型塩類細胞の分化を促す。海水型塩類細胞は隣接する［D］と呼ばれる小型の細胞と細胞複合体を形成することが多い。",
