    "explanation": "淡水ではプロラクチンが塩類の流失を抑え、糸球体濾過などを通じて余分な水の排出を助ける。間腎組織由来のコルチゾルは海水適応に関与し、鰓の塩類細胞はアクセサリー細胞と複合体を作る。",
