    "difficulty": 3,
    "question": "水産成分の利用に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　甲殻類の殻に含まれているキチンは、D-グルコースから成る多糖であり、キトサンはそのアセチル化体である。生体適合性の高いキチンは、手術用縫合糸などの医療材料としての利用が進んでいるほか、コンドロイチンの原料となっている。\nB　褐藻類に含まれているアルギン酸は、L-グルロン酸とD-マンヌロン酸を構成糖とする多糖である。アルギン酸のナトリウム塩の水溶液は粘度の高いゾルであるが、カルシウムイオン存在下ではゲル化する。アルギン酸のナトリウム塩は、増粘剤や安定剤として利用されている。\nC　魚の鱗や皮に含まれているコラーゲンには、リジンやアルギニンが構成アミノ酸として多く含まれる。コラーゲンを主成分としたゼラチンは、食品の固化剤として利用される。また、コラーゲンの加水分解物であるヒアルロン酸は化粧品等としても利用される。\nD　赤色カロテノイドであるアスタキサンチンは、微細緑藻、甲殻類、サケ・マス類などに含まれている。アスタキサンチンは優れた抗酸化活性を有しており、化粧品やサプリメントとして利用されている。また、カロテノイドの一部の分子種は、プロビタミンAとしての機能を持っている。",
