      "エ": "アルギン酸はマンヌロン酸とグルロン酸からなり、カルシウムイオンによる架橋でゲル化する。アスタキサンチンは様々な藻類や水産動物に見られる赤色のカロテノイドで、抗酸化性を利用した製品に使われる。",
