    "question": "作物における光合成産物などの輸送に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　光合成により生産される同化産物は、葉から茎を経て全量が花と実に輸送され、器官の形成や維持、貯蔵物質の合成に利用される。同化産物を供給する器官をソース、同化産物を利用・貯蔵する器官をシンクという。ソースとシンクの能力は互いに影響を受けず、独立している。\nB　根と葉など離れた器官の間での長距離輸送は維管束を通じて行われており、木部は根で吸収された水や無機養分を地上部へと運ぶ主要な輸送経路である。木部の中にある道管は細胞壁が肥厚し、細胞内容物が分解・脱落したアポプラストである。\nC　炭水化物やアミノ酸などの同化産物は師管を通じて輸送される。師管は師要素と呼ばれる特殊な細胞からできており、網目状につながって構成されている。師要素は核やゴルジ体、液胞といったオルガネラを失っており、死んだ細胞とみなされている。\nD　器官におけるソースやシンクとしての役割は、固定的なものではなく、変化する場合がある。例えば、イネの葉鞘や稈は、出穂前にはシンクとして働くが、出穂後にはソースとして働き、同化産物が穂に転流される。",
