    "difficulty": 3,
    "question": "野菜種苗の繁殖方法に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　種子繁殖は容易に大量の種苗を生産できる繁殖様式である。得られた種子の寿命は長く、例えばホウレンソウでは採種後10年経過した場合も発芽率が9割を超える。また、種子繁殖のうち、アンフィミクシスと呼ばれる無性生殖では親株と同じ遺伝子型を持つ種子を得ることができるため、雑種強勢の固定などに利用されることがある。\nB　ウイルスフリー苗を作る手段としては、茎頂培養法やカルス培養法などがある。茎頂培養法では一般にウイルスやウイロイドが侵入できない維管束を無菌的に切り出して組織培養し、ウイルスフリー苗を取得する。この方法で作出された苗はプロトプラストと呼ばれる。\nC　いも、球根などの栄養体によって、無性的に個体数を増やす繁殖様式を栄養繁殖という。挿し木は、茎、葉、根などを用いた栄養繁殖方法で、一般に茎を保水性のある用土に挿し、不定根の発生を促す。このため、挿し木では親株と同じ遺伝形質を持つクローン個体を得ることができる。\nD　葯培養では花粉の培養により半数体の作出が可能である。さらにコルヒチン処理により、半数体の染色体を倍加し、遺伝子型がホモ接合の個体を作出することで、遺伝形質の固定を行う初期の数世代を省略し、育種年限を短縮することができる。",
    "choices": {
      "ア": "A、B",
      "イ": "A、C",
      "ウ": "A、D",
      "エ": "B、C",
      "オ": "C、D"
    },
    "answer": "オ",
    "officialAnswerNumber": 5,
    "explanation": "挿し木は体細胞由来の栄養体から不定根を出させるので、原則として親株と同じ遺伝子型を持つ。葯培養で生じる半数体の染色体を倍加すると遺伝子座がホモ接合になり、系統固定を早められる。",
