      "ウ": "Dの倍加半数体育種では同じ染色体を二組にするためホモ接合性を一世代で得られる。Aの種子の寿命は保存条件などで変わり、アンフィミクシスは無性生殖ではない。",
      "エ": "Cは妥当である。茎頂培養で用いるのは維管束自体ではなく、生長点を含む茎頂の小組織である。",
