      "イ": "ネギは、中国が原産とされる野菜である。緑植物春化型の野菜で、ある程度大きくなった苗が低温にさらされると花芽分化する。千住群などの根深ネギの栽培においては、通気性の良い土壌が好ましく、白い葉鞘部を得るために土寄せをする。",
