      "イ": "植物のゲノムDNAでは、グアニンがメチル化修飾されることがある。遺伝子のプロモーター部位にメチル化されたグアニンが分布すると、転写因子などがプロモーター部位に結合できなくなることで転写が抑制される。DNAのメチル化状態は塩基配列の変化を伴わないので、次世代の個体へ継承されない。",
