      "エ": "標準遺伝暗号はタンパク質を作る20種類の基本アミノ酸に対応する。標準的な開始コドンAUGが指定するのはメチオニンである。",
      "オ": "mRNAは5′から3′に向かって翻訳され、ポリペプチド鎖はN末端からC末端へ伸びる。コード領域の5′側がN末端、3′側がC末端に対応する。"
