    "difficulty": 3,
    "question": "育種に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　自殖性作物の育種法のうち、純系選抜法（純系分離法）は交雑を伴わない。系統育種法及び集団育種法は交雑育種法であるため、自殖性作物の育種集団内の変異を拡大する。集団選抜法は他殖性作物の育種法であり、古くから用いられている育種法である。\nB　イネ、コムギ、ジャガイモ及びサツマイモの品種は、収穫物を種苗として毎年の栽培を続けても、品種内の遺伝子型頻度が変わらない。この状態は、ハーディー・ワインベルグの法則における平衡状態であり、ヘテロ接合型がなく、ホモ接合型のみが維持されている。\nC　環境に強く影響される形質は遺伝率が高いので、自殖性作物において選抜を行う場合は、表現型選抜又はDNAマーカー選抜のいずれにおいても、遺伝子型変異に富む雑種初期世代（F₂～F₃）での選抜が適している。\nD　一代雑種育種法においては、インブレッドラインが雑種種子（F₁種子）を生産する際の親系統に用いられる。自殖種子の混入を防ぐ自家不和合性は、インブレッドラインの維持を容易にする上で、有用な形質の一つである。アブラナ科の自家不和合性は、つぼみ受粉やエチレンガス処理などにより打破される。",
