    "question": "一代雑種品種と雄性不稔に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　一代雑種品種は、雑種強勢により旺盛な生育や多収を示すが、形質の均一性は劣る。一代雑種品種は、イネなどの自殖性作物では開発されていないが、トウモロコシなどの他殖性作物では数多く開発されている。\nB　一代雑種品種の採種には、単交雑、複交雑、三系交雑などが用いられている。複交雑や三系交雑は、近交弱勢のために自殖系統から十分な採種量が得られない場合に用いられる。また、一代雑種品種の採種には、自家不和合性や雄性不稔が利用されている。\nC　細胞質雄性不稔は、葉緑体ゲノムの遺伝子に由来し、母性遺伝する。一代雑種品種を、細胞質雄性不稔の種子親と交雑して作出する際、タマネギやダイコンでは核に稔性回復遺伝子を持つ花粉親を利用しなければならないが、トウモロコシやセイヨウナタネでは核に稔性回復遺伝子を持たない花粉親も利用できる。\nD　細胞質雄性不稔では、細胞質が不稔の原因遺伝子を持たなければ、花粉稔性の回復をもたらす核遺伝子が潜性ホモ接合型であっても花粉ができる。この花粉を細胞質雄性不稔の種子親と交雑すると、得られる子孫は全て可稔個体となり、この花粉親を稔性回復系統という。",
