    "question": "植物病害を対象とした生物的防除に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　病原菌に対して寄生や捕食といったアレロパシーを示す微生物の一部は、生きた状態のまま製剤化され生物的防除資材として販売されているが、自然由来のため慢性毒性試験や農薬登録は必要ない。製剤化されている微生物には、バチルス属、シュードモナス属の細菌やトリコデルマ属の糸状菌などがある。\nB　微生物を用いた生物的防除資材のメリットは、環境負荷が小さいこと、病原体が耐性を獲得しにくいこと、化学農薬に比べて防除効果が安定していること、大量生産が容易であり価格帯が低いことなどが挙げられる。一方、デメリットは、微生物としての活性を維持しなければならないため保存安定性の確保が難しいことなどが挙げられる。\nC　生きている植物内に共生するエンドファイトや、植物の根に共生するアーバスキュラー菌根菌の一部は、病気の発生を抑止する。エンドファイトによる発病抑制はハクサイ根こぶ病などで報告されている。またエンドファイトに感染した植物は耐虫性が高まる事例も知られている。\nD　ウイルスが植物に感染すると、その植物は近縁のウイルスに感染しにくくなる現象があり、干渉作用という。これを利用して、病原性が極めて低い弱毒ウイルスがウイルス病の予防に使用されており、我が国では、ズッキーニ黄斑モザイクウイルスの弱毒株などが実用化されている。弱毒ウイルスは自然界からの選抜及び分離、又は人為的な突然変異の誘発によって作出される。",
