      "ウ": "Bには汚泥肥料の区分に誤りがある。Cで単肥を機械的に混ぜたものは一般に配合肥料と呼ばれる。",
      "エ": "Dは堆肥中の炭素と窒素の比率に応じた土壌での効果を正しく述べている。Bには特殊肥料に汚泥肥料を含める誤りがある。",
      "オ": "Dは妥当である。Cの機械的混合による説明は配合肥料に対応し、高度化成の副成分が普通化成より多いともいえない。"
