      "イ": "カルビンとベンソンらは、放射性同位元素である¹⁸Oを用いて、CO₂の同化初期産物を発見し、続けて代謝経路が回路状であることも発見した。この炭酸固定の代謝回路はカルビン・ベンソン回路、若しくは反応物質名からGS/GOGATサイクルと名付けられ、11種の酵素による13の反応から成る。",
