    "difficulty": 3,
    "question": "需要曲線が線形で右下がりであり、企業の費用曲線が同一で線形である寡占市場に関する記述A〜Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. クールノー・ナッシュ均衡における総生産量は、完全競争市場の総生産量よりも少ないものの独占市場の最適生産量よりは多くなる。また、均衡における寡占企業の利潤の和は独占企業の利潤より小さくなるという特徴を持つ。\n\nB. 同質の財をめぐって寡占企業が価格競争した場合の均衡をシュタッケルベルク均衡と呼び、寡占企業が共謀して価格をつり上げることからの抜け駆けを罰するメカニズムが働かない場合には、価格は完全競争と同じ水準となり、企業利潤の和はクールノー・ナッシュ均衡における企業利潤の和と一致する。\n\nC. 先に生産量を選ぶリーダーと、それを見て生産量を選ぶフォロワーを想定したベルトラン・モデルにおける均衡では、リーダーの生産量はフォロワーの生産量よりも小さくなり、利潤はゼロである。\n\nD. 独占的競争市場では、個々の企業が差別化された製品を生産するため、短期では独占企業と同じような利潤最大化行動をとる。一方、長期では完全競争市場と同じように経済的利潤がゼロになるまで企業参入が続く。",
