    "difficulty": 3,
    "question": "次は、マクロ経済モデルに関する記述であるが、ア、イ、ウに当てはまるものの組合せとして最も妥当なのはどれか。\n\n海外との貿易が行われていない閉鎖経済において、下記のマクロ経済モデルが与えられている。\n\n財市場の均衡：Y = C + I + G\n消費関数：C = 50 + c(Y − T)（ただし、0 < c < 1とする）\nY：国民所得、C：消費、I：投資、G：政府支出、c：限界消費性向、T：租税\n\nいま、I = 150、G = 80、c = 0.8、T = 100、完全雇用国民所得が［ア］であるとき、この経済における［イ］は200であり、政府支出を200増加させることで完全雇用国民所得を達成することができる。\n\nまた、税額が所得水準に応じて変動するよう、T = 0.05Yとした場合、政府支出増加による乗数効果はT = 100の場合と比べて［ウ］。",
