    "question": "次は、農業における経営組織に関する記述であるが、A〜Fに当てはまるものの組合せとして最も妥当なのはどれか。\n\n米国農務省（USDA）の農業統計では、農場の法的形態（Legal Status）として、個人・家族経営のほか、パートナーシップ、家族会社、非家族会社といった類型が示されている。下の図は、各指標における個人・家族経営の割合を示したものであるが、個人・家族経営の割合は、［A］ベースでみた場合が最も高く、次いで［B］、［C］の順となっている。このように個人・家族経営の割合が高い要因として、農地取引を通じた規模拡大の速度より、労働生産性の向上（1 ha当たり必要労働時間の減少）の速度が［D］ことが挙げられる。\n\nこのことから、農地の利用が比較的少ない我が国の養豚部門における経営形態別の構成を説明することもできる。我が国の農林業センサスでは、経営形態として個人経営体・団体経営体という枠組みが用いられているが、下の表にあるように、養豚における飼養経営体数・飼養頭数ともに［E］が［F］よりも割合が高くなっている。",
