    "question": "次の図は、輸入が行われている農産物Xの関税賦課前後の状況を示している。このとき、ア〜エを表すものの組合せとして最も妥当なのはどれか。ただし、関税賦課による変化を答える際には、関税賦課後の値から関税賦課前の値を差し引くこととする。また、ここでの自給率は国内需要量に占める国内供給量で求められるものとする。\n\nア：関税賦課による自給率の変化\nイ：関税賦課による政府収入\nウ：関税賦課による死荷重\nエ：関税賦課による消費者余剰の変化",
