    "difficulty": 3,
    "question": "次は、生産者の費用最小化行動と、異なる二つの技術に関する記述であるが、ア、イ、ウに当てはまるものの組合せとして最も妥当なのはどれか。\n\n図は、それぞれ異なる生産関数上で、同じ水準の生産量Ȳを生産できる労働Lと資本Kの集合を表した等量曲線F₁及びF₂を示したものである。これらの曲線の接線の傾きの大きさは技術的限界代替率と呼ばれ、F₁上、F₂上それぞれで費用最小化が成立している点において、（労働限界生産力）/（賃金） = ［ア］が常に成立している。F₁上のE₁及びF₂上のE₂は、ある賃金w、ある資本賃貸率rの下での費用最小化点である。このとき、賃金一定の下で資本賃貸率が［イ］すると、F₁上の費用最小化点はE₃に、F₂上の費用最小化点はE₄に移る。E₃とE₄における費用を比較すると［ウ］の費用の方が低い。",
