    "question": "次は、需要関数とその推定に関する記述であるが、ア、イ、ウに当てはまるものの組合せとして最も妥当なのはどれか。\n\n過去50年の年次データを用いて、次の(1)式で表される農産物Xの需要関数を最小二乗法で推定したい。\n\nlog(qₜ) = α + βlog(pₜ) + γlog(yₜ) + eₜ　(1)\n\nただし、qₜ：t年の農産物Xの需要量、pₜ：t年の農産物Xの価格、yₜ：t年の家計所得、eₜ：誤差項とし、logは自然対数を表す。α、β、γはパラメータである。\n\n(1)式においてα = 7.2、β = −0.5、γ = 0.2であった場合、所得のみの変化によって農産物Xの需要が10％増加したとき、所得の増加率は、［ア］％である。(1)式の推定には、時系列データが用いられているため、推定の際には、誤差項に［イ］が生じる可能性に留意する必要がある。［イ］の有無を検定するための統計的検定方法として、［ウ］検定が知られている。",
