    "difficulty": 3,
    "question": "次は、令和7（2025）年4月に策定された食料・農業・農村基本計画（以下「基本計画」という。）に関する記述であるが、A、B、Cに当てはまるものの組合せとして最も妥当なのはどれか。\n\n新たな基本計画は、令和6（2024）年に改正された食料・農業・農村基本法において定められた「食料安全保障の確保」「環境と調和のとれた食料システムの確立」「多面的機能の発揮」「農業の持続的な発展」「農村の振興」の五つの基本理念の実現に向け、施策をテーマごとに整理し、今後の施策の方向性を具体化したものである。\n\n新たな基本計画では、平時からの食料安全保障を実現するため、従来の食料自給率目標に加え、その他の食料安全保障の確保に関する目標が設定された。［A］を目標年として、基本計画の各テーマの現状や課題、課題解決の具体的施策を踏まえた目標及び施策の有効性を示すKPIが設定されている。\n\n「我が国の食料供給」に向けては、人・農地等の資源をフル活用し、食料自給力を確保することが必要であることから、担い手の育成・確保、多様な農業者による適正な農地の保全・管理、生産性の向上等を図ることとされ、［B］や農地面積、生産コストの低減等について目標が設定された。これに加えて、農業生産において必要不可欠な生産資材の安定的な供給、国内生産だけでは賄えない食料の安定的な輸入の確保、不測の事態に備えた備蓄の確保を図ることとされた。\n\nまた、農業者及び食品事業者の収益性の向上に資するよう、今後成長する海外の食市場を取り込むことが重要であることから、輸出拡大等による「海外から稼ぐ力」の強化を図ることとされ、我が国の農林水産物・食品の輸出額を［C］とする目標を掲げるとともに、食品産業の海外展開及びインバウンドによる食関連消費の拡大に向けても、それぞれ施策を強化することとされた。\n\n国として食料の総量を確保するだけでなく、「国民一人一人の食料安全保障」を確保するためには、食料の生産から消費に至る各段階の関係者が有機的に連携した「持続的な食料システム」を構築する必要がある。これに向けて、食品アクセスの確保や食品産業の持続的発展を図ることとされ、関連する目標やKPIが設定された。",
