    "question": "我が国の農村振興施策などに関する記述A〜Dのうち、妥当なもののみを挙げているのはどれか。なお、データは「令和6年度 食料・農業・農村白書（令和7年5月30日公表）」による。\n\nA. 中山間地域をはじめとした農村地域では、小規模化による集落機能の低下が懸念されている。このため、複数の集落の機能を補完し、農用地保全活動や農業を核とした経済活動と併せて、生活支援等の地域コミュニティ維持に資する取組を行う農村型地域運営組織（農村RMO）の形成が推進されている。\n\nB. 農福連携に取り組む主体数は、令和元（2019）年度以降令和5（2023）年度にかけて減少傾向で推移しており、取組の推進を目指して農福連携等推進ビジョン（2024改訂版）が決定された。これに基づき、政府は「障害者が生産行程に携わった食品及び観賞用の植物」に関するGI商品の普及など、国民的運動として農福連携を推進している。\n\nC. 農泊とは、農山漁村に宿泊し、滞在中に豊かな地域資源を活用した食事や体験等を楽しむ農山漁村滞在型旅行のことである。農泊地域への延べ宿泊者数は新型コロナウイルス感染症の影響により大きく減少したが、令和4（2022）年度には令和元年度の延べ宿泊者数を超えた。\n\nD. 平成27（2015）年に比べ令和2（2020）年の人口は全ての都道府県で減少しているが、特に農村地域で人口減少と高齢化が進んでいる。こうした農村地域の支えとなる人材の裾野を拡大していくためには、農村関係人口の創出・拡大が必要である。農村関係人口とは、長期的な定住人口でも、短期的な交流人口でもない、地域や地域の人々と継続的に多様な形で関わる者の総称である。",
