    "question": "次は、家畜の妊娠と分娩に関する記述であるが、A〜Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n妊娠認識とは、胚が分泌する妊娠シグナル物質により、［A］が抑制され、妊娠が成立・維持される仕組みである。ウシではインターフェロンτ、ブタでは［B］がシグナル物質として作用し、それぞれプロスタグランジンF₂α（PGF₂α）の分泌抑制及び分泌方向の変化に関与する。ウシやヒツジの分娩発来は、胎子の［C］から分泌されるコルチゾール分泌量の増加により誘導される。ウシの分娩過程は、三つの段階に分けられ、開口期では子宮収縮により陣痛が生じる。産出期では、まず［D］の破れによる第一破水が起こり、第二破水、胎子の娩出へと続く。後産期では、［E］時間以内に胎盤の排出が行われるが、それを超えると胎盤停滞とされる。",
