    "question": "乳牛の産乳技術や泌乳期における管理に関する記述A〜Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 分娩後に採食量は増加するが、泌乳量はそれよりも遅れて増加するので、泌乳中後期は負のエネルギーバランスになりやすい。エネルギー不足を起因とする脂肪壊死症などの疾病への罹患を防ぐためにも、適切な飼養管理を行うことが重要である。\n\nB. 泌乳持続性は、遺伝的能力の評価形質の一つであり、泌乳前期と後期の乳量の差が小さいほど高くなる。泌乳持続性の高い牛は、1泌乳期における泌乳量の変化が小さいため、泌乳持続性の低い牛と比べて飼養管理が容易になる。\n\nC. 労働時間の削減を目的として、搾乳ロボットの導入が進んでいる。フリーストール牛舎に導入する場合は、搾乳牛の動線を考慮した場所に搾乳機を設置し、ロボット内で濃厚飼料を給与する等、搾乳牛が自発的にロボットへ進入するように誘導する必要がある。\n\nD. 周産期に起こりやすい低カルシウム（Ca）血症は、泌乳による乳中への急激なCa分泌とルーメンからのCa吸収抑制によって引き起こされる。予防には、分娩前にビタミンAを筋肉注射することが有効である。",
