    "question": "次は、家畜の生体における内分泌系による調節に関する記述であるが、A〜Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\nホルモンは、内分泌器官から分泌され、主に血液を介して標的の細胞へと到達する。ホルモンの持つ調節作用は、細胞に存在する受容体と結合することにより発揮されるが、受容体は、細胞膜上に存在するものと、細胞内に存在するものの二つに大別され、ステロイド型のホルモンは［A］の受容体に結合する。主要な内分泌器官の一つである下垂体からは様々なホルモンが分泌され、下垂体前葉からは［B］、下垂体後葉からは［C］などが分泌されている。また、膵臓も下垂体と同様に重要な内分泌器官である。膵臓内部には、数種類の内分泌細胞から構成された膵島（ランゲルハンス島）が存在しており、膵島の［D］からは、栄養素代謝の制御において非常に重要な役割を担っているインスリンが分泌される。",
