    "question": "次は、漁獲努力量と生産金額の関係等に関する記述であるが、A、B、Cに当てはまるものの組合せとして最も妥当なのはどれか。\n\n図の曲線は、生産物価格が一定であるときの、長期における漁獲努力量と生産金額の関係を表している。E（MEY）は、MEY（最大経済生産量）を与える漁獲努力量であり、直線（ア）は、漁獲努力の単位当たり費用が一定の下で漁獲に必要な費用を表している。\n\nオープンアクセス、すなわち漁業への参入が自由な状況下では、利潤が［A］まで参入が続くため、漁獲の単位当たり費用が［B］ほど、資源がより強度に利用される。こうした状況において、MEYの達成を目指す方法の一つに課税がある。例えば、漁獲努力に対し、漁獲努力量一単位当たり一定の税を適切な水準で課すことができれば、費用を直線（ア）から［C］へと変化させ、均衡を点Pへと移動させることができる。",
