    "difficulty": 3,
    "question": "我が国における漁業制度や水産政策に関する記述A〜Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 近年、陸地で行う養殖業への新規参入が活発化し、その管理が必要になったため、令和5（2023）年4月より、内水面漁業の振興に関する法律に基づいて、陸上養殖業の一部は許可が必要となった。一方で、現在内水面で営まれている養殖業のうち、古くから河川沿い等で営まれているマス、アユ、コイ等の淡水かけ流し式養殖については、引き続き届出のみで営むことができる。\n\nB. 悪質な密漁が行われているうなぎの稚魚、あわび及びなまこは令和7（2025）年末時点で「特定水産動植物」に指定されており、漁業権や漁業の許可等に基づいて採捕する場合を除いて、採捕が原則禁止とされ、違反した場合には罰則が科される。また、違法に採捕されたことを知りながら、「特定水産動植物」を取り扱った販売業者等に対しても、密漁者と同じ罰則が適用される。\n\nC. 特定水産動植物等の国内流通の適正化等に関する法律では、輸入規制を講ずることが必要な水産動植物を、「特定第二種水産動植物」（さば、さんま、まいわし及びいか（対象魚種は令和6年度末時点））と定義している。この制度は、輸入される特定の水産動植物について、適法性を証明する仕組みとすることで、IUU（違法・無報告・無規制）漁業由来の漁獲物が我が国へ流入することを防ぐものである。\n\nD. 近年、全国の都市漁村交流人口が減少し続けている中、豊かな自然や漁村ならではの地域資源の価値や魅力を活かした「海業」の取組の推進により、地域の所得向上等を図ることが必要となっている。「海業」は、令和4（2022）年の水産基本計画において、「農林漁業と、製造業、小売業等の事業との総合的かつ一体的な推進を図り、地域資源を活用した新たな付加価値を生み出す取組」と定義されている。",
