    "question": "次は、我が国のいか釣り漁業に関する記述であるが、A〜Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\nいか釣り漁業の操業方法には、探索操業や漂流操業等がある。探索操業では、船下の方向に超音波を発射する［A］や、水平方向に超音波を発して船の周囲を探索する［B］を使って魚群を捉え、釣具を降下することで漁獲する。漂流操業では、夜間、パラシュートアンカーを利用して船首を風上に向け、船を潮に乗せて流しながら漁獲する。夜間の操業で用いられる漁灯として、現在、［C］が普及しているが、よりエネルギー効率の高いLED（発光ダイオード）灯の導入も進められている。\n\nいか釣り漁業の主な漁獲対象である［D］の漁獲量は、近年大きく減少している。その要因の一つとして、平成28（2016）年以降、冬季発生系群と秋季発生系群の資源量が減少したことがある。こうした変化に対応するため、総トン数30トン以上のいか釣り漁船の一部では、5〜9月に太平洋中央部（東経170度から西経160度の海域）で安定した漁獲量が見込まれる、［E］を対象とした操業を再開する動きがみられる。",
