    "question": "我が国の水産資源の調査、評価、管理に関する記述A〜Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 平成30（2018）年に改正され、令和2（2020）年に施行された漁業法では、都道府県知事及び市町村長は、資源評価を行うために必要な情報を収集するための資源調査を行うこと、農林水産大臣は、都道府県知事に対して資源評価の要請ができることが規定されている。\n\nB. 資源調査は、漁獲・水揚げ情報の収集、操業・漁場環境情報の収集、調査船による調査、海洋環境と資源変動の関係解明等から成り、行政機関、研究機関、漁業者が連携して取り組んでいる。これらの調査から得られる情報を基に、研究機関が資源評価を実施している。\n\nC. 行政機関は、乱獲を未然に防止するための目標管理基準値、最大持続生産量を達成するための限界管理基準値及び漁獲管理規則（漁獲シナリオ）を事前に定める。これらに基づいて、研究機関が資源評価を行う。この結果を基に、行政機関はTAC（漁獲可能量）、IQ（個別割当）等の管理措置を決定する。\n\nD. 管理措置には、TACやIQによる公的な規制のほかに、網目制限、保護区の設定、休漁などによる自主的取組がある。自主的取組の一部は、資源管理協定として、農林水産大臣又は都道府県知事の認定を受ける。資源管理協定は、取組内容等の公表を通じて、管理目標を達成することを目指している。",
