      "ウ": "懸濁物質が少ない外洋では青の光が海中から戻ってくるため青く見える。植物プランクトンの光合成速度は弱い光で増え、強くなると飽和し、過度の光では強光阻害を受け得る。",
      "エ": "Bは光合成色素の分類と吸収域が誤っている。Cの補償深度は光と呼吸の条件によって変わり、光がより深く届く透明な水域で深くなりやすい。",
      "オ": "Dの光強度と光合成の関係は妥当である。Bのプランクトンの主要な色素にはカロテノイドがあり、ベタレインをその分類に入れる点が誤りである。"
