    "difficulty": 3,
    "question": "我が国における内湾域の漁場環境に関する記述A〜Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 内湾域の多くは河川の影響下にある。河口域では陸域から淡水が供給されるため、上層で低塩分水が沖に向かい、下層では高塩分水が岸に向かうエスチュアリー循環が生じる。大きな河川が流入する内湾域では、河口域に比べて規模の大きなエスチュアリー循環が生じる。\n\nB. 2000年代以降の瀬戸内海における赤潮の発生件数は、赤潮防止対策などにより、1970年代後半の10分の1程度にまで減少している。2020年以降では、瀬戸内海における有害赤潮による漁業被害は報告されていない。\n\nC. 栄養塩類の減少等が、養殖ノリの色落ちや魚介類の減少要因となっている可能性が、漁業者や地方公共団体の研究機関から指摘されている。兵庫県、山口県及び香川県では栄養塩類管理計画が策定され、水質の改善と水産資源の持続可能な利用の確保の調和・両立が進められている。\n\nD. 東北海域や九州海域において発生が報告される貝毒は、工業廃水などに含まれる重金属の蓄積により、可食部が毒化し発生する。我が国では、令和7（2025）年3月時点において、麻痺性貝毒、下痢性貝毒及び記憶喪失性中毒による食中毒の報告がある。",
