    "question": "海洋の循環や海流に関する記述A〜Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 地球規模の海洋循環である深層循環は、高緯度域での冷却と結氷に伴う塩分増加によって重くなった海水が、深く沈降することで形成される。深層循環の大規模な沈降は、グリーンランド周辺、南極のウェッデル海周辺で生じ、大西洋の南北で形成された深層水が、インド洋を経由して太平洋に運ばれる過程で、表層に湧昇する。\n\nB. 亜熱帯循環は、偏西風と極偏東風の影響で生じる表層でのエクマン輸送によって形成される。黒潮は、北太平洋の亜熱帯循環における西岸境界流である。気象庁では、黒潮が足摺岬から安定して離岸していること及び東海沖での流路の最南下点が北緯35度以南に位置していることをもって、黒潮大蛇行と判定している。\n\nC. 太平洋の赤道帯付近では、南北両半球側にある貿易風帯に対応して、北赤道海流と南赤道海流が東向きに流れる。これらの両赤道海流の間では、赤道反流が西向きに流れる。また、両貿易風帯が赤道に対して南北非対称であるため、北赤道海流は南にずれ、赤道付近にある。\n\nD. 親潮は、東カムチャッカ海流から続く寒流であり、千島列島に沿って南下し、本州東方海域まで達する。親潮の最大流速は、一般に、黒潮の最大流速よりも小さい。本州東方海域では、親潮の水が南方に舌状の形で張り出すことがあり、このような舌状の冷水部は岸から順に、第1分枝、第2分枝と呼ばれる。",
