    "question": "魚病に関する記述A〜Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. マダイイリドウイルス病はred seabream iridovirusによる感染症である。マダイ以外にも、ブリ、ヒラメ、トラフグなど30種以上の海産魚での罹患が確認されており、脾臓の肥大などの病状を呈する。我が国では、マダイ及びブリ属魚類に対するワクチンが市販されている。\n\nB. せっそう病は、主にトラフグにみられる感染症であり、病魚の体表面には瘤状の隆起が認められる。本症は、グラム陽性細菌Aeromonas salmonicidaに由来する。本細菌は、鞭毛での運動性を有し、培養すると水溶性の緑色色素を培地中に産生することから、病原菌を容易に同定することが可能である。\n\nC. α溶血性レンサ球菌症は、グラム陽性の連鎖球菌Lactococcus garvieaeによって引き起こされ、ブリ、カンパチ、ヒラマサなどのブリ属魚類や、シマアジ、サバなどに感染する。本細菌に感染すると、眼球の白濁及び突出などの病状を呈する。ブリ属魚類に対してはワクチンが承認されている。\n\nD. ブリのべこ病は、単生類寄生虫Benedenia seriolaeによる疾病であり、本寄生虫がブリの体側筋細胞に寄生してシストを形成する。胞子形成終了後のシスト崩壊とともにブリの筋肉組織が融解するため、体側に特徴的なV字型の出血が生じる。食用魚におけるべこ病対策として、水産用医薬品であるマラカイトグリーンの使用が認められている。",
