    "difficulty": 3,
    "question": "魚類の生殖腺と配偶子形成に関する記述A〜Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. 魚類の卵巣は、サケやウナギなどにみられる嚢状型と、ヒラメやキンギョなどが有する裸状型に大別される。卵巣内は多数の卵巣薄板で仕切られ、その中には多くの卵濾胞が存在する。卵濾胞は、卵母細胞とそれを取り囲む胞嚢から構成される。\n\nB. 卵原細胞が減数分裂を開始し、第二減数分裂後期に達したものを卵母細胞と呼ぶ。卵母細胞は囲卵腔によって取り囲まれ、卵黄胞や油球、卵黄球などを蓄積して成長する。その後、嚢状型卵巣では体腔に、裸状型卵巣では卵巣腔に排卵される。\n\nC. 生殖腺刺激ホルモン放出ホルモン（GnRH）は下垂体で産生される。GnRHは、視床下部に作用して濾胞刺激ホルモン（FSH）の分泌を促し、さらにFSHが卵濾胞での黄体形成ホルモン（LH）の産生を促進する。\n\nD. 生殖腺では、生殖腺刺激ホルモンの作用によって様々な性ホルモンが産生される。エストラジオール17β（E₂）は、卵巣でつくられる代表的な性ホルモンであり、肝臓に作用して卵黄タンパク質の前駆体であるビテロジェニンの合成を促進する。",
