    "question": "魚類の栄養要求及び飼餌料に関する記述A〜Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 魚類における飼料中の炭水化物の利用性は、食性によって異なる。デンプンの飼料中適正量は、コイ科魚類においては40〜50％程度であるが、魚食傾向が高いブリにおいては5％以下である。飼料中の炭水化物は、エネルギー源以外の役割もあり、カルボキシメチルセルロースは粘結剤として使用される。\n\nB. 魚類は、グリシンやシスチンなどを含めた合計8種類のアミノ酸を必須アミノ酸として要求する。タウリンはトリプトファンから生合成されるが、海水魚の一部はタウリン合成能力が低いため、飼料中にタウリンを要求することがある。\n\nC. モイストペレットは、生餌と比較して、栄養剤や油脂の添加が容易である一方、水中での離散性が高くなる。海水魚用飼料として普及しているエクストルーデッドペレットは、油脂を高含有できるため肉食性魚類に適しているが、多孔質であるため沈降性の調節は困難である。\n\nD. 魚類において、植物原料に含まれるフィチン酸や、魚粉に含まれる第三リン酸カルシウムは、ミネラルの利用性を低下させる。魚類が要求するミネラルの一つである亜鉛の欠乏は、白内障を引き起こすことがある。",
