    "difficulty": 3,
    "question": "次は、水産成分の分析手法に関する記述であるが、A〜Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n生体成分の主要な分析方法の一つとして分離分析がある。例として、水産脂質の［A］の分析には簡便かつ高感度なガスクロマトグラフィー（GC）が用いられることが多い。本手法では、前処理として試料のカルボキシ基をメチルエステル化し、極性を低下させるのが一般的である。GCの定量分析には［B］が、定性分析には質量分析器が用いられることが多い。\n\n一方、分光分析も様々な成分分析に利用される。生鮮魚類の鮮度指標であるK値の測定や、酵素免疫測定法（ELISA）には、可視紫外分光計が用いられる。可視紫外分光法において、試料のモル濃度と［C］は比例関係にある。また、化合物における吸収スペクトルの極大値の波長を吸収極大波長と呼び、物質の［D］に依存する値のため、化合物の同定にも利用される。",
