    "officialAnswerNumber": 4,
    "explanation": "脂肪酸をメチルエステルにしてGCで分離し、水素炎イオン化検出器で定量できる。一定の光路長などの条件では吸光度が濃度に比例し、吸収極大波長は分子の化学構造を反映する。",
