      "ウ": "吸光度は妥当である。記述の対象と定量法は脂肪酸組成と水素炎イオン化検出器で、吸収極大波長は化学構造に依存する。",
      "エ": "脂肪酸をメチルエステルにしてGCで分離し、水素炎イオン化検出器で定量できる。一定の光路長などの条件では吸光度が濃度に比例し、吸収極大波長は分子の化学構造を反映する。",
      "オ": "脂肪酸組成と化学構造は妥当である。GCの定量には水素炎イオン化検出器が広く用いられ、濃度と直線関係にあるのは透過度でなく吸光度である。"
