    "difficulty": 3,
    "question": "水産動植物の育種に関する記述A〜Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 育種目標となる形質は、質的形質と量的形質に分けられる。質的形質は、体長などの表現型が連続的変異を示す形質のことである。遺伝率とは、対象とした集団中の変異のうち遺伝的要因による変異の割合を示し、遺伝率が低いほど個体の人為選択が効果的である。\n\nB. 魚類の三倍体は、一般に、受精直後の卵に、低温処理又は高温処理などの温度処理や、加圧処理を行い、第1極体の放出を阻止することで、卵由来の染色体を2セット、精子由来の染色体を1セット、それぞれ保持させることで作出される。一般に、魚類の三倍体にみられる有用な特徴として、性成熟年齢の若齢化が挙げられる。\n\nC. アマノリ類は、大型の配偶体世代と微小な胞子体世代を繰り返す異型世代交代を行う。胞子体はコンコセリスとも呼ばれ、成熟すると殻胞子を放出する。コンコセリスの発見によってアマノリ類の全生活環が明らかとなり、優良な種や系統の保存が可能となった。\n\nD. マーカー選抜育種法とは、目的形質の原因遺伝子と連鎖したDNA多型を検出するDNAマーカーを指標として、親魚選抜を行う方法である。マーカー選抜育種法により、ヒラメのリンホシスチス病耐病性系統が開発・市販されている。",
    "choices": {
      "ア": "A、B",
      "イ": "A、C",
      "ウ": "B、C",
      "エ": "B、D",
      "オ": "C、D"
    },
    "answer": "オ",
    "officialAnswerNumber": 5,
    "explanation": "アマノリ類は葉状の配偶体と微小な糸状の胞子体を交互に形成する。目的形質と連鎖するDNAマーカーを使った選抜は、ヒラメの耐病性系統の作出にも用いられた。",
