    "difficulty": 3,
    "question": "有害微細藻類とその毒性に関する記述A〜Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. アミノ酸の一種であるドウモイ酸は、グルタミン酸受容体に作用する中枢神経性の毒であり、Pseudo-nitzschia属の渦鞭毛藻や、ホンダワラ科の大型褐藻が生産する。ドウモイ酸は、駆虫薬の成分としても知られている。\n\nB. オカダ酸は、Dinophysis属の緑藻が生産する脂溶性物質であり、神経性貝毒の原因物質の一つである。一般的な加熱調理では毒性は失活しない。我が国では食品衛生法によって規制値が定められており、値を超えるものは出荷規制される。\n\nC. ミクロシスチン類は、Microcystis属などの藍藻類が産生するペプチドであり、強い肝毒性を示す。国外では、Microcystis属などによるアオコの影響で、家畜やヒトの死亡事故も起きている。\n\nD. 我が国沿岸では、Chattonella属のラフィド藻による赤潮が度々発生し、魚類の大量斃死を引き起こしている。これらが魚類を斃死させる機構は、Chattonella属による活性酸素の生産や、魚類の鰓における粘液物質による閉塞などの要因が複合的に関与していると考えられている。",
